import{_ as o,o as t,c as a,a3 as s}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Help Desk — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Help Desk — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/help-desk"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Help Desk — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/help-desk"}]]},"headers":[],"relativePath":"deployment/help-desk.md","filePath":"deployment/help-desk.md","lastUpdated":1787238031000}'),n={name:"deployment/help-desk.md"};function i(r,e,l,d,c,p){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="help-desk-—-production-guide" tabindex="-1">Help Desk — Production Guide <a class="header-anchor" href="#help-desk-—-production-guide" aria-label="Permalink to &quot;Help Desk — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>help-desk</code></li><li>Category: <code>operations</code> (<strong>Operations</strong>), <code>category_sort_order = 40</code>, <code>sort_order = 10</code></li><li><strong>Free Marketplace opt-in</strong> module (not auto-installed)</li><li>Catalog flags: <code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code></li><li><strong>No hard module dependency</strong> — Help Desk installs standalone; Contacts and Companies are optional soft links, only offered in the UI (and only validated) when already entitled</li><li>New workspaces receive only <strong>Leads</strong> + <strong>Tasks</strong> + <strong>ToDos</strong> by default; enable Help Desk from Marketplace at any time</li><li>Existing workspaces that already have Help Desk keep their subscription</li><li>Deactivate via Central module subscription tools to revoke access without dropping data</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create (Central tenant create or public register):</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules (<strong>Leads</strong>, <strong>Tasks</strong>, <strong>ToDos</strong> only)</li><li>Operators enable <strong>Help Desk</strong> from Marketplace whenever needed — no prerequisite modules</li><li>Tenant permissions include <code>help-desk.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li></ol><p>No status seeder — ticket status defaults to <code>open</code> at creation. Categories (General / Technical / Billing / Account / Other) lazy-seed on first category list or ticket create — not via <code>db:seed</code>.</p><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Help Desk permissions for <strong>existing</strong> workspaces ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code>. Do <strong>not</strong> re-seed roles or rely on login/dashboard to repair RBAC.</p><h2 id="tenant-settings" tabindex="-1">Tenant settings <a class="header-anchor" href="#tenant-settings" aria-label="Permalink to &quot;Tenant settings&quot;">​</a></h2><p><code>help_desk_number_prefix</code> (default <code>HD-</code>) controls the auto-generated <code>number</code> prefix. Updatable via <code>PUT /api/tenant/v1/settings</code>.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>help_desk_ticket_created</code>, <code>help_desk_ticket_updated</code>, <code>help_desk_ticket_deleted</code>, <code>help_desk_ticket_assigned</code>, <code>help_desk_ticket_status_changed</code>, <code>help_desk_ticket_note_added</code></li><li>Spatie activity log name <code>help-desk-categories</code> for category CRUD (lazy seed is quiet)</li><li>Notifications: assignment, close, reopen (database + mail) via <code>HelpDeskAssignedNotification</code> / <code>HelpDeskStatusNotification</code></li><li>Tenant mail settings with Central SMTP fallback</li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate help desk tables (<code>help_desk_categories</code>, <code>help_desk_tickets</code>, <code>help_desk_notes</code>, <code>help_desk_activities</code>) and register catalog module <strong>1.0.0</strong></li><li>Register the <code>help-desk</code> catalog module (migration, not seeder) as free opt-in under the <code>operations</code> category — <strong>no</strong> <code>module_dependencies</code> row</li><li>Migrate <code>help-desk.*</code> permissions and grant to existing <code>admin</code> / <code>manager</code> / <code>staff</code> roles per default maps</li><li>Confirm <code>module:help-desk</code> + <code>help-desk.*</code> permissions on target roles</li><li>Deploy frontend (Help Desk nav under <strong>Operations</strong> — list/form/detail + <strong>Manage categories</strong>; dashboard <code>help_desk_my_open</code> widget)</li><li>Smoke: create a <strong>new</strong> workspace → enable Help Desk (alone, no CRM modules) → Manage categories → create a custom category → create/edit/assign/note a ticket → transition statuses → close → reopen → soft delete/restore</li><li>Smoke (soft links): on a workspace with Contacts + Companies + Help Desk → create a ticket with contact/company links → confirm links resolve in detail</li><li>Smoke (soft-gate off): on a workspace with Help Desk but <strong>without</strong> Contacts → confirm contact/company pickers are hidden</li></ol><h2 id="roadmap-context" tabindex="-1">Roadmap context <a class="header-anchor" href="#roadmap-context" aria-label="Permalink to &quot;Roadmap context&quot;">​</a></h2><p>Help Desk is the first <strong>Operations</strong> Marketplace SKU — internal ticketing MVP only. SLAs, multi-channel intake, customer portal, and Knowledge Base remain future. See <a href="/architecture/module-dependencies">module-dependencies.md</a> and <a href="/getting-started/product-roadmap">product-roadmap.md</a>.</p>',17)])])}const h=o(n,[["render",i]]);export{m as __pageData,h as default};
